css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; overflow: hidden; }
.loader .ramp { position: absolute; left: 5%; width: 90%; height: 4.5%; border-radius: 999px; background: linear-gradient(90deg, var(--accent-2), color-mix(in srgb, #000 26%, var(--accent-2))); }
.loader .ramp:nth-child(1) { top: 24%; transform: rotate(8deg); }
.loader .ramp:nth-child(2) { top: 54%; transform: rotate(-8deg); }
.loader .ramp:nth-child(3) { top: 84%; transform: rotate(8deg); }
.loader span { position: absolute; width: 13%; height: 13%; border-radius: 50%; background: radial-gradient(circle at 34% 30%, color-mix(in srgb, #fff 52%, var(--accent)), var(--accent)); animation: descend calc(var(--loader-speed) * 3) linear infinite; }
.loader span:nth-child(5) { animation-delay: calc(var(--loader-speed) * -1.5); }
@keyframes descend { 0% { opacity: 0; left: 3%; top: 8%; } 8% { opacity: 1; } 26% { left: 79%; top: 20%; } 34% { left: 81%; top: 44%; } 56% { left: 5%; top: 52%; } 64% { left: 3%; top: 74%; } 86% { left: 79%; top: 82%; } 96% { opacity: 1; left: 81%; top: 96%; } 100% { opacity: 0; left: 81%; top: 100%; } }
